FiniteFieldMixing.productDensity_coeff.exact_printed_type:
@FiniteFieldMixing.productDensity_coeff : ∀ {p : ℕ} [inst : Fact (Nat.Prime p)] (χ : AddChar (ZMod p) ℂ)
  (H : Finset (ZMod p)) (r : ZMod p),
  FiniteFieldMixing.coeff χ (FiniteFieldMixing.productDensity H) r = FiniteFieldMixing.normalizedProductCoeff χ H H r

FiniteFieldMixing.productSumProbability_.exact_printed_type:
@FiniteFieldMixing.productSumProbability_lower_bound : ∀ {p : ℕ} [inst : Fact (Nat.Prime p)] (H : Finset (ZMod p)),
  H.Nonempty →
    ∀ (k : ℕ) (z : ZMod p), (1 - (↑p - 1) * (√↑p / ↑H.card) ^ k) / ↑p ≤ FiniteFieldMixing.productSumProbability H k z

FiniteFieldMixing.four_product_nat_lift.exact_printed_type:
@FiniteFieldMixing.four_product_nat_lift : ∀ {p : ℕ} [inst : Fact (Nat.Prime p)] (D : Finset ℕ),
  p ^ 3 ≤ (Finset.image Nat.cast D).card ^ 4 →
    ∃ a b, (∀ (i : Fin 4), a i ∈ D) ∧ (∀ (i : Fin 4), b i ∈ D) ∧ p ∣ ∑ i, a i * b i
